package com.kuaima.app.admin.entity;
import java.math.BigDecimal;import java.time.LocalDateTime;import jakarta.persistence.*;import lombok.Getter;import lombok.Setter;
@Entity @Table(name="reward_campaign",indexes={@Index(name="idx_reward_status_send",columnList="status,send_at"),@Index(name="idx_reward_created",columnList="created_at"),@Index(name="idx_reward_target",columnList="target")}) @Getter @Setter
public class RewardCampaign {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true,length=40)private String rewardNo;@Column(nullable=false,length=100)private String name;@Column(nullable=false,length=20)private String target;@Column(nullable=false,length=20)private String scope;@Column(columnDefinition="TEXT")private String users;private Integer plannedCount;@Column(nullable=false,length=20)private String amountMode;@Column(precision=18,scale=2)private BigDecimal amount;@Column(precision=18,scale=2)private BigDecimal minAmount;@Column(precision=18,scale=2)private BigDecimal maxAmount;@Column(precision=18,scale=2)private BigDecimal totalAmount;@Column(nullable=false,length=20)private String status;private String sendMode;private LocalDateTime sendAt;private LocalDateTime createdAt;@Column(length=500)private String remark;private Long operatorId;private String operatorName;private Integer actualCount=0;@Column(precision=18,scale=2)private BigDecimal actualAmount=BigDecimal.ZERO;private Integer failedCount=0;@Column(length=1000)private String errorMessage;
 public void setAmount(Long v){amount=v==null?null:BigDecimal.valueOf(v,2);}public void setAmount(long v){amount=BigDecimal.valueOf(v,2);}public void setMinAmount(Long v){minAmount=v==null?null:BigDecimal.valueOf(v,2);}public void setMinAmount(long v){minAmount=BigDecimal.valueOf(v,2);}public void setMaxAmount(Long v){maxAmount=v==null?null:BigDecimal.valueOf(v,2);}public void setMaxAmount(long v){maxAmount=BigDecimal.valueOf(v,2);}public void setTotalAmount(Long v){totalAmount=v==null?null:BigDecimal.valueOf(v,2);}public void setTotalAmount(long v){totalAmount=BigDecimal.valueOf(v,2);}public void setActualAmount(Long v){actualAmount=v==null?null:BigDecimal.valueOf(v,2);}public void setActualAmount(long v){actualAmount=BigDecimal.valueOf(v,2);}
 public void setAmount(BigDecimal v){amount=v;}public void setMinAmount(BigDecimal v){minAmount=v;}public void setMaxAmount(BigDecimal v){maxAmount=v;}public void setTotalAmount(BigDecimal v){totalAmount=v;}public void setActualAmount(BigDecimal v){actualAmount=v;}
}
